     *
     * @return string|null
     */
    public function getExplorerStatus()
    {
        return $this->container['explorer_status'];
    }

    /**
     * Sets explorer_status
     *
     * @param string|null $explorer_status explorer_status
     *
     * @return self
     */
    public function setExplorerStatus($explorer_status)
    {
        if (is_null($explorer_status)) {
            throw new \InvalidArgumentException('non-nullable explorer_status cannot be null');
        }
        $allowedValues = $this->getExplorerStatusAllowableValues();
        if (!in_array($explorer_status, $allowedValues, true)) {
            throw new \InvalidArgumentException(
                sprintf(
                    "Invalid value '%s' for 'explorer_status', must be one of '%s'",
                    $explorer_status,
                    implode("', '", $allowedValues)
                )
            );
        }
        $this->container['explorer_status'] = $explorer_status;

        return $this;
    }

